        # Detect this by looking for rows with year prefix
        has_year_prefix = False
        for i in range(hi + 1, min(hi + 50, len(lines))):
            line = lines[i]
            if '|' in line:
                parts = [p.strip() for p in line.split('|')]
                if len(parts) > 2 and parts[1]:
                    if '1947-January' in parts[1] or '1947-February' in parts[1]:
                        has_year_prefix = True
                        break

        current_year = None

        for i in range(hi + 1, min(hi + 80, len(lines))):
            line = lines[i]
            if '|' not in line:
                continue

            parts = [p.strip() for p in line.split('|')]
            if len(parts) < 9:
                continue

            col1 = parts[1]

            # Year row - update current year
            if col1.isdigit() and len(col1) == 4:
                current_year = int(col1)
                continue

            # Year-month row - extract year and month
            if '-' in col1 and not col1.startswith('-'):
                parts_date = col1.split('-')
                if len(parts_date) == 2 and parts_date[0].isdigit():
                    current_year = int(parts_date[0])
                    col1 = parts_date[1]

            # Check if this is our target month with correct year
            if col1 == target_month_name:
                # For 1948, handle the case where months without prefix are for previous year
                expected_year = target_year
                if has_year_prefix and current_year is None:
                    # If we have year-prefixed months, then non-prefixed months are for 1947
                    # We need to handle this differently
                    pass
                elif current_year == expected_year:
                    try:
                        value_str = parts[8].replace(',', '').strip()
                        value = float(value_str)
                        if value > 500:
                            return value
                    except:
                        continue

    return None

# Let me try a more direct approach - look in later bulletins for 1948 data
# 1948-10 should have data for up to September 1948 in some form
print("Direct search for 1948 data:")

